import json
from http.server import BaseHTTPRequestHandler
from reportlab.lib.pagesizes import letter
from reportlab.lib.units import inch
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Image, HRFlowable
from reportlab.lib.enums import TA_CENTER, TA_LEFT
from reportlab.lib import colors
import io
import base64
import tempfile
import os

LOGO_B64 = """"""


def build_pdf(data):
    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=letter,
                            leftMargin=0.75 * inch, rightMargin=0.75 * inch,
                            topMargin=0.6 * inch, bottomMargin=0.6 * inch)

    dark = colors.HexColor("#1a1a1a")
    accent = colors.HexColor("#2c3e50")
    light_gray = colors.HexColor("#95a5a6")

    title_style = ParagraphStyle('Title', fontSize=20, alignment=TA_CENTER,
                                  spaceAfter=2, fontName='Helvetica-Bold',
                                  textColor=dark)
    subtitle_style = ParagraphStyle('Subtitle', fontSize=10, alignment=TA_CENTER,
                                     spaceAfter=6, fontName='Helvetica',
                                     textColor=light_gray)
    heading_style = ParagraphStyle('SectionHead', fontSize=11, fontName='Helvetica-Bold',
                                    spaceBefore=18, spaceAfter=6,
                                    textColor=accent,
                                    borderPadding=(0, 0, 4, 0))
    body_style = ParagraphStyle('Body', fontSize=10, fontName='Helvetica',
                                 spaceAfter=3, leading=14, leftIndent=12,
                                 textColor=dark)
    meta_label = ParagraphStyle('MetaLabel', fontSize=9, fontName='Helvetica-Bold',
                                 textColor=light_gray, spaceAfter=1)
    meta_val = ParagraphStyle('MetaVal', fontSize=11, fontName='Helvetica',
                               spaceAfter=8, textColor=dark)

    elements = []

    # Logo
    logo_bytes = base64.b64decode(LOGO_B64)
    logo_tmp = tempfile.NamedTemporaryFile(delete=False, suffix='.png')
    logo_tmp.write(logo_bytes)
    logo_tmp.close()
    try:
        logo = Image(logo_tmp.name, width=1.8 * inch, height=0.74 * inch)
        logo.hAlign = 'CENTER'
        elements.append(logo)
    except Exception:
        pass
    finally:
        os.unlink(logo_tmp.name)

    elements.append(Spacer(1, 8))
    elements.append(Paragraph("Weekly Progress Report", title_style))
    elements.append(Spacer(1, 2))
    elements.append(HRFlowable(width="40%", thickness=1, color=accent,
                                spaceAfter=16, hAlign='CENTER'))

    # Meta info
    elements.append(Paragraph("DATE", meta_label))
    elements.append(Paragraph(data.get('date', 'N/A'), meta_val))
    elements.append(Paragraph("PROJECT", meta_label))
    elements.append(Paragraph(data.get('project', 'N/A'), meta_val))
    elements.append(Paragraph("WEEK OF", meta_label))
    elements.append(Paragraph(data.get('weekOf', 'N/A'), meta_val))

    elements.append(HRFlowable(width="100%", thickness=0.5, color=colors.HexColor("#e0e0e0"),
                                spaceAfter=6, spaceBefore=6))

    # Sections
    sections = [
        ("WORK PERFORMED THIS WEEK", data.get("workPerformed", [])),
        ("WORK SCHEDULED FOR NEXT WEEK", data.get("workScheduled", [])),
        ("MODIFICATIONS TO THE PROJECT", data.get("modifications", [])),
        ("APPROVALS NEEDED", data.get("approvals", [])),
        ("PRESENT AND/OR ANTICIPATED PROBLEMS", data.get("problems", [])),
        ("HOT LIST — CRITICAL ITEMS TO STAY ON TRACK", data.get("hotList", [])),
    ]

    for title, items in sections:
        elements.append(Paragraph(title, heading_style))
        elements.append(HRFlowable(width="100%", thickness=0.5, color=colors.HexColor("#e0e0e0"),
                                    spaceAfter=6))
        if items and len(items) > 0:
            for item in items:
                elements.append(Paragraph(f"\u2022  {item}", body_style))
        else:
            elements.append(Paragraph("N/A", body_style))

    doc.build(elements)
    return buf.getvalue()


class handler(BaseHTTPRequestHandler):
    def do_POST(self):
        try:
            content_length = int(self.headers.get("Content-Length", 0))
            body = json.loads(self.rfile.read(content_length))

            pdf_bytes = build_pdf(body)
            pdf_b64 = base64.b64encode(pdf_bytes).decode("utf-8")

            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(json.dumps({"pdf": pdf_b64}).encode())
        except Exception as e:
            self.send_response(500)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps({"error": str(e)}).encode())

    def do_OPTIONS(self):
        self.send_response(200)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.end_headers()
